cypress_script:
describe('Test Case Listing Page', () => {
  it('should display the test cases correctly', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.title().should('eq', 'Automation Practice Website for UI Testing - Test Cases');
    cy.contains('Test Cases').should('be.visible');
    cy.get('a').contains('Test Case 1: Register User').should('be.visible');
    cy.get('a').contains('Test Case 2: Login User with correct email and password').should('be.visible');
  });
  it('should not navigate away when subscribing without an email', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.get('#susbscribe_email').clear();
    cy.get('#subscribe').click();
    cy.url().should('eq', 'https://automationexercise.com/test_cases');
    cy.get('a').contains('Test Case 1: Register User').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Test Case Listing Page', () => {
  test('should display the test cases correctly', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await expect(page).toHaveTitle('Automation Practice Website for UI Testing - Test Cases');
    await expect(page.locator('text=Test Cases')).toBeVisible();
    await expect(page.locator('a:has-text("Test Case 1: Register User")')).toBeVisible();
    await expect(page.locator('a:has-text("Test Case 2: Login User with correct email and password")')).toBeVisible();
  });
  test('should not navigate away when subscribing without an email', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await page.fill('#susbscribe_email', '');
    await page.click('#subscribe');
    await expect(page).toHaveURL('https://automationexercise.com/test_cases');
    await expect(page.locator('a:has-text("Test Case 1: Register User")')).toBeVisible();
  });
});
